import {SOURCES as S} from './content-authoring.mjs';
const q=(question,options,body,reasons)=>({q:question,correct:options[0],wrong:options.slice(1),body,wrongReasons:reasons,application:false});
const card=(question,answer,example,pitfall)=>({q:question,a:answer,example,pitfall});
const workshop=(chapter,title,context,sections,table,quiz,cards,sources=[])=>({chapter,title,context,sections:sections.map(([title,...paragraphs])=>({title,paragraphs})),table:table?{headers:table[0],rows:table[1]}:null,quiz,cards,sources});
// Authored situations and corrections, not imported textbook excerpts or random variants.
export const SUBJECT_WORKSHOPS={
 UE1:workshop('preuve-obligation','Facture, obligation et paiement',
 'Atelier original. Une prestataire réclame 1 200 € pour une mission. Le client reconnaît la commande mais affirme avoir payé. Le dossier contient le devis accepté et la facture, sans relevé ni reçu du règlement.',[
 ['Répartir les questions de preuve','La discussion contient deux questions différentes : une obligation de payer existe-t-elle et cette obligation a-t-elle été éteinte ? Le devis accepté éclaire l’engagement ; la facture exprime une demande de paiement. Aucun de ces documents ne démontre à lui seul un transfert de fonds.','La personne qui demande l’exécution doit étayer l’obligation invoquée. Celle qui affirme être libérée doit justifier le paiement ou l’autre fait libératoire. Ce raisonnement sur la charge de la preuve ne dispense pas d’examiner l’admissibilité et la portée des pièces dans le cadre du dossier.'],
 ['Écrire une conclusion proportionnée','Évitez « le client doit forcément payer deux fois » ou « la facture prouve qu’il a payé ». Présentez l’engagement documenté, puis l’affirmation de paiement encore à étayer. Un reçu ou un mouvement bancaire doit être relié à cette dette : même montant, bénéficiaire et référence utiles.','Une copie solide distingue ce qui est reconnu, ce qui est contesté et la preuve attendue. Elle ne transforme pas une absence de pièce dans l’énoncé en certitude qu’aucun paiement n’a jamais eu lieu.']],
 [['Pièce ou affirmation','Ce qu’elle éclaire','Ce qu’elle ne suffit pas à établir'],[['Devis accepté','Commande et engagement','Paiement effectif'],['Facture de 1 200 €','Somme réclamée et opération','Extinction de la dette'],['« J’ai payé »','Position du client','Réalité du règlement']]],[
 q('Atelier facture et paiement : quel fait le devis accepté éclaire-t-il ?', ['L’engagement lié à la commande.','Le virement exécuté.','L’extinction certaine de la dette.','Le préjudice du client.'],'Le devis accepté renseigne sur la commande et l’engagement. La preuve d’un règlement porte sur un événement distinct.',['Le devis n’est pas un mouvement bancaire.','Un engagement et son extinction sont deux faits distincts.','Aucun dommage n’est décrit dans cette pièce.']),
 q('Dans cet atelier, qui doit étayer le paiement invoqué comme fait libératoire ?', ['Le client qui affirme avoir payé.','La prestataire dans tous les cas.','Un tiers choisi au hasard.','Personne, une affirmation suffit.'],'La personne qui se prétend libérée doit justifier le fait libératoire. La prestataire doit, de son côté, étayer l’obligation dont elle réclame l’exécution.',['Cela confond preuve de l’obligation et preuve de son extinction.','La charge ne se déplace pas vers un tiers arbitraire.','L’affirmation seule ne justifie pas le fait contesté.']),
 q('Un relevé montre un paiement de 1 200 € à un autre bénéficiaire. Quelle analyse retenir ?', ['Le lien avec la dette litigieuse reste à établir.','Le montant suffit à prouver le paiement de cette dette.','Toute dette du client est éteinte.','Le devis devient automatiquement nul.'],'Le montant concordant ne suffit pas : il faut relier le paiement à la dette et au créancier concernés.',['Le bénéficiaire est une donnée pertinente.','Un règlement ne libère pas de toutes les dettes.','La pièce de paiement ne démontre pas un défaut de validité du devis.']),
 q('Quelle conclusion respecte les informations de cet atelier ?', ['L’engagement est documenté ; le paiement annoncé reste à étayer.','Aucun paiement n’a certainement jamais eu lieu.','La facture est une quittance.','Le client doit payer deux fois.'],'La conclusion sépare le fait documenté de celui qui manque de justification dans le dossier.',['L’absence de pièce fournie n’est pas la preuve universelle d’une absence de paiement.','Une facture n’est pas, par nature, une quittance.','Cette conclusion ignore la question du règlement déjà invoqué.'])
 ],[
 card('Preuve d’une dette : quelles deux questions séparer ?','L’existence de l’obligation et le fait qui aurait éteint cette obligation.','Une commande acceptée peut établir l’engagement sans démontrer son paiement.','Ne pas confondre facture et quittance.'),
 card('Fait libératoire : à qui rattacher sa justification ?','À la personne qui se prétend libérée, dans le raisonnement de l’article 1353 du Code civil.','Le débiteur qui invoque un virement doit le relier à la dette.','La preuve de l’obligation reste une question distincte.'),
 card('Paiement : pourquoi le montant concordant ne suffit-il pas toujours ?','Il faut aussi vérifier le bénéficiaire et le lien avec l’obligation concernée.','Deux factures différentes peuvent avoir le même montant.','Ne pas attribuer un paiement à une dette par simple ressemblance.'),
 card('Dossier incomplet : comment rédiger la conclusion sur le paiement ?','Décrire les éléments établis et nommer la preuve encore nécessaire.','« Paiement annoncé, mais non justifié par les pièces fournies. »','Ne pas transformer une lacune de l’énoncé en certitude absolue.')
 ],[['Charge de la preuve, Code civil article 1353','https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000032042341/']]),
 UE2:workshop('financement','Trois flux, trois qualités',
 'Atelier original. Nora souscrit 15 000 € au capital, prête 6 000 € à la société et signe séparément une caution de 4 000 €. Le dossier ne donne pas les modalités du prêt ni celles de la garantie.',[
 ['Raisonner par opération','La banque de la société reçoit 21 000 €, mais ce total n’est ni un chiffre d’affaires ni un capital de 21 000 €. La souscription et le prêt produisent des droits différents. Nora peut être associée au titre des 15 000 € et créancière au titre du prêt, sans que ces qualités lui donnent automatiquement tous les pouvoirs de signature.','Pour qualifier chaque flux, recherchez l’acte : souscription, convention de prêt, engagement de garantie. Le compte courant d’associé n’est pas un dividende ; son remboursement dépend du cadre et des conditions à examiner.'],
 ['Lire les risques séparément','La caution ne constitue pas une troisième entrée de 4 000 € en banque. Elle est un engagement personnel distinct. Son existence, son étendue et ses conditions ne se déduisent pas du montant du capital ni de la seule qualité d’associée.','Dans une réponse d’examen, distinguez patrimoine de la société et engagements personnels. Ne calculez pas une exposition certaine de 25 000 € en additionnant des objets de nature différente. Présentez les montants, leur nature et les vérifications nécessaires.']],
 [['Montant','Opération','Qualité ou contrôle'],[['15 000 €','Souscription au capital','Droits sociaux selon les titres'],['6 000 €','Prêt à la société','Créance et conditions de remboursement'],['4 000 €','Caution distincte','Engagement personnel à examiner']]],[
 q('Atelier Nora : quel montant est versé au titre de la souscription au capital ?', ['15 000 €.','21 000 €.','25 000 €.','6 000 €.'],'Les 15 000 € relèvent de la souscription ; les 6 000 € sont un prêt distinct.',['Ce total comprend le prêt.','La garantie n’est pas un apport versé.','Ce montant correspond au prêt.']),
 q('Les 6 000 € prêtés donnent principalement quelle relation dans cet atelier ?', ['Une relation de créancier à débiteur.','Une vente de marchandises.','Un dividende déjà distribué.','Une augmentation automatique de 6 000 € du capital.'],'Le prêt se distingue des droits sociaux et des revenus de l’activité.',['Aucune vente n’est décrite.','Une somme prêtée n’est pas un dividende reçu.','Un prêt ne devient pas une souscription par sa seule réception.']),
 q('Que faut-il examiner pour apprécier la caution de Nora ?', ['L’acte de garantie et ses conditions.','Uniquement le chiffre d’affaires.','Uniquement la couleur des titres.','La garantie disparaît dès que Nora est associée.'],'La garantie personnelle doit être analysée dans son propre cadre.',['Le chiffre d’affaires ne décrit pas cet engagement.','La couleur n’est pas un critère juridique.','La qualité d’associée ne neutralise pas automatiquement une garantie distincte.']),
 q('La société reçoit 21 000 €. Peut-on qualifier tout ce montant de vente ?', ['Non : ce sont ici une souscription et un prêt.','Oui, toute entrée en banque est une vente.','Oui, parce que Nora est associée.','Oui, mais seulement les 4 000 € de caution.'],'La qualification d’un flux vient de l’opération et non du seul mouvement de banque.',['Un encaissement peut provenir d’un financement.','La qualité de la personne ne transforme pas les opérations.','La caution ne décrit pas un encaissement de vente.'])
 ],[
 card('Financement : capital et prêt d’associé donnent-ils les mêmes droits ?','Non : les titres et la créance de prêt correspondent à des relations distinctes.','15 000 € souscrits et 6 000 € prêtés ne constituent pas 21 000 € de capital.','Ne pas classer tout financement en vente.'),
 card('Garantie personnelle : quel document examiner en priorité ?','L’acte de garantie, sa portée et ses conditions.','Une caution peut concerner une personne qui est aussi associée.','Ne pas supposer que la qualité d’associé efface la garantie.'),
 card('Compte courant d’associé : que faut-il vérifier avant un remboursement ?','La nature du solde et les conditions de remboursement applicables.','Une convention peut prévoir un blocage.','Ne pas promettre une disponibilité immédiate sans lire les conditions.'),
 card('Dossier de financement : quel tableau préparer ?','Personne, qualité, opération, montant, droit ou engagement et document.','Séparer apport, prêt et caution dans trois lignes.','Additionner des montants ne remplace pas leur qualification.')
 ],[S.company,S.civil]),
 UE3:workshop('modification-remuneration','Proposition, accord et bulletin de paie',
 'Atelier original. Le contrat prévoit 2 000 € bruts mensuels. L’employeur propose 1 800 €. La salariée demande des explications ; aucun accord n’est fourni. Le bulletin suivant affiche 1 800 €.',[
 ['Comparer les faits sans supposer le consentement','La variation chiffrée est une baisse de 200 €, soit 10 % de la base contractuelle donnée. Ce calcul décrit l’écart ; il ne tranche pas la régularité de la mesure. La rémunération contractuelle appelle un contrôle de l’accord dans le cadre pertinent.','La demande d’explications ne prouve pas une acceptation. Le bulletin montre ce qui a été versé, mais pas, à lui seul, que la modification a été valablement convenue. Le contrat, la proposition, les échanges et un éventuel avenant n’ont donc pas la même portée.'],
 ['Ne pas inventer la suite du litige','Le dossier permet d’identifier une modification proposée et un écart de versement. Il ne permet pas de conclure à une démission ni de déterminer automatiquement l’issue d’une procédure de rupture. Ces questions nécessitent leurs propres faits et règles.','La réponse doit distinguer rémunération prévue, proposition, consentement à vérifier et montant versé. En cas de désaccord, expliquez l’information et le fondement à examiner plutôt que d’annoncer une sanction certaine.']],
 [['Élément','Montant ou contenu','Portée'],[['Contrat','2 000 € bruts','Rémunération prévue'],['Proposition','1 800 € bruts','Changement souhaité'],['Demande d’explications','Pas d’accord fourni','Consentement non établi'],['Bulletin','1 800 € bruts','Versement constaté']]],[
 q('Atelier rémunération : quelle baisse est proposée par rapport à 2 000 € ?', ['10 %.','11,11 %.','200 %.','90 %.'],'La baisse vaut (2 000 − 1 800) / 2 000 = 10 %.',['Cette valeur utilise 1 800 comme dénominateur.','200 € n’est pas un pourcentage de 200 %.','90 % est le niveau restant, pas la baisse.']),
 q('La demande d’explications prouve-t-elle un accord à la baisse ?', ['Non, elle ne suffit pas à établir l’acceptation.','Oui, toute question vaut acceptation.','Oui, car le contrat est écrit.','Oui, si la paie a déjà été calculée.'],'Il faut distinguer réaction à une proposition et consentement à la modification.',['Une question et une acceptation sont des actes distincts.','Le contrat initial ne prouve pas l’accord au changement.','La préparation de la paie ne démontre pas le consentement.']),
 q('Que montre directement le bulletin à 1 800 € dans cet atelier ?', ['Le montant de rémunération versé.','L’accord certain à toute modification.','Une démission.','La disparition du contrat initial.'],'Le bulletin documente la rémunération versée ; son fondement contractuel reste à analyser.',['Versement et consentement ne se confondent pas.','Aucune volonté de démission n’est établie.','Un bulletin ne supprime pas automatiquement le contrat.']),
 q('Quelle organisation de réponse convient au dossier social ?', ['Contrat, proposition, réponse, versement, contrôles juridiques.','Conclusion de rupture avant lecture des faits.','Montants seuls sans les documents.','Supposition d’un avenant absent.'],'La chronologie aide à rattacher chaque affirmation à une pièce avant d’examiner les conséquences.',['La rupture demande des faits et conditions distincts.','Le calcul ne remplace pas la qualification.','Une pièce absente ne doit pas être inventée.'])
 ],[
 card('Rémunération contractuelle : proposition et accord sont-ils équivalents ?','Non. L’accord à la modification doit être examiné distinctement de sa proposition.','Une demande d’explications n’établit pas seule une acceptation.','Ne pas inventer un avenant.'),
 card('Baisse de rémunération : quel dénominateur utiliser pour le taux de variation ?','La rémunération initiale.','De 2 000 à 1 800 : baisse de 200 / 2 000 = 10 %.','Ne pas diviser l’écart par la rémunération finale.'),
 card('Bulletin de paie : quelle distinction conserver dans un litige ?','Le versement constaté et le fondement juridique de ce versement.','Un bulletin à 1 800 € ne prouve pas seul l’accord à une baisse.','Le document ne tranche pas toutes les questions du contrat.'),
 card('Chronologie sociale : quels événements relier aux pièces ?','Situation initiale, proposition, réponses, mise en œuvre et démarches.','Séparer le contrat du bulletin et des courriels.','Un refus de modification ne doit pas être assimilé automatiquement à une démission.')
 ],[['Modification du contrat de travail, Service Public','https://www.service-public.gouv.fr/particuliers/vosdroits/F2339']]),
 UE4:workshop('tva','TVA de période : calculer sans oublier les conditions',
 'Atelier original. Une période comporte 2 400 € HT de ventes au taux fourni de 20 %, 200 € de TVA d’achat déductible selon les hypothèses et un crédit antérieur de 80 €. Aucun autre mouvement ni ajustement n’est donné.',[
 ['Séparer le montant et le droit à déduction','Le montant de taxe d’une facture et sa déductibilité sont deux contrôles. Dans l’atelier, les 200 € sont explicitement considérés déductibles et imputables à la période. Hors de cette hypothèse, il faut examiner justificatif, affectation de l’achat, exigibilité et éventuelles exclusions.','Le taux fourni sert à convertir la base HT des ventes en taxe collectée. Il ne faut pas appliquer 20 % au montant TTC ni traiter la taxe collectée comme un revenu supplémentaire de l’activité. Le crédit antérieur est une donnée distincte des achats de la période.'],
 ['Présenter un rapprochement lisible','La taxe collectée est de 480 €. Après déduction des 200 € et imputation du crédit de 80 €, le solde est de 200 € à payer sous les seules hypothèses de l’exercice. Présentez chaque ligne au lieu de donner un nombre sans origine.','Si le solde calculé était négatif, il faudrait parler d’un crédit, puis vérifier les conditions de report ou de remboursement. Un crédit calculé n’est pas un encaissement automatique du même montant.']],
 [['Ligne de liquidation','Calcul','Montant'],[['TVA collectée','2 400 × 20 %','480 €'],['TVA déductible fournie','Imputation de période','−200 €'],['Crédit antérieur','Imputation fournie','−80 €'],['Solde','480 − 200 − 80','200 € à payer']]],[
 q('Atelier TVA de période : taxe collectée sur 2 400 € HT au taux donné de 20 % ?', ['480 €.','400 €.','2 880 €.','200 €.'],'TVA collectée = base HT × taux : 2 400 × 0,20 = 480 €.',['400 € correspondrait à extraire 20 % d’un TTC de 2 400 €.','2 880 € est le TTC des ventes dans cette hypothèse.','200 € est ici le solde après imputations.']),
 q('Avec 480 € collectés, 200 € déductibles et 80 € de crédit antérieur, quel solde ?', ['200 € à payer.','280 € à payer.','760 € à payer.','200 € de crédit.'],'Le rapprochement est 480 − 200 − 80 = 200, positif donc à payer.',['Le crédit antérieur a été oublié.','Les imputations ne s’ajoutent pas à la taxe collectée.','Un solde positif de ce rapprochement n’est pas un crédit.']),
 q('Pourquoi l’atelier précise-t-il que les 200 € de TVA d’achat sont déductibles ?', ['Parce que taxe facturée et droit à déduction sont deux contrôles.','Toute TVA est déductible sans condition.','Une facture est inutile.','La TVA déductible est toujours un produit.'],'Le calcul suppose que justificatif, affectation et période de déduction permettent l’imputation indiquée.',['Le droit à déduction est conditionné.','Le justificatif est un élément du contrôle.','Cette taxe ne se classe pas automatiquement en produit.']),
 q('Un autre dossier aboutit à un crédit. Que ne faut-il pas présumer ?', ['Un remboursement automatique et immédiat.','L’existence d’un solde à analyser.','La possibilité d’examiner le report.','La nécessité de vérifier les conditions.'],'L’imputation, le report et le remboursement doivent être distingués.',['Ce n’est pas une présomption fautive : le solde doit être analysé.','Le report est une option à examiner, pas une erreur.','Le contrôle des conditions reste nécessaire.'])
 ],[
 card('TVA : quelle relation lie HT, taxe et TTC pour un taux fourni ?','Taxe = HT × taux ; TTC = HT + taxe.','2 400 € HT à 20 % donnent 480 € de taxe et 2 880 € TTC.','Appliquer le taux à un TTC surestime la taxe.'),
 card('TVA de période : où intervient un crédit antérieur donné ?','Il s’impute séparément dans le rapprochement, sous les hypothèses du dossier.','480 − 200 − 80 = 200 € à payer.','Ne pas le confondre avec la taxe d’achat courante.'),
 card('Déduction de TVA : que vérifier au-delà du montant de facture ?','Justificatif, affectation, exigibilité, période et exclusions pertinentes.','La taxe chiffrée ne suffit pas à établir le droit à déduction.','Un montant connu n’est pas une autorisation d’imputation.'),
 card('Crédit de TVA : quelle distinction garder ?','Crédit calculé, report et remboursement sont des objets distincts.','Un solde négatif ne crée pas un versement automatique.','Vérifier les conditions du régime concerné.')
 ],[S.vat]),
 UE5:workshop('production','Valeur, volume et contribution productive',
 'Atelier original. Une activité produit pour 360 000 € et consomme 144 000 € de biens et services intermédiaires. Sa production précédente vaut 300 000 €. L’indice des prix cohérent avec cette production passe de 100 à 108.',[
 ['Décrire ce que l’indicateur mesure','Dans le schéma de cet atelier, la valeur ajoutée est 360 000 − 144 000 = 216 000 €. Elle ne constitue pas le bénéfice : rémunérations, autres éléments et conventions de mesure restent à distinguer. Soustraire les consommations intermédiaires évite de compter leur valeur comme une création propre de l’activité.','La production courante dépasse la production antérieure de 20 % en valeur. Cette mesure combine prix et volume. L’indice des prix fourni permet ici une décomposition simplifiée cohérente ; un indice portant sur un autre panier ne devrait pas être utilisé sans justification.'],
 ['Déflater puis interpréter','L’indice de valeur est 120, celui des prix 108. L’indice de volume vaut 120 / 108 × 100 = 111,11 environ, soit une hausse de 11,11 %. Soustraire mécaniquement 8 points à 20 % donne une approximation, pas le calcul exact.','Une hausse en volume ne démontre pas à elle seule une hausse de productivité. Pour cela, il faut une mesure des ressources mobilisées. Une explication économique doit relier mesure, mécanisme possible et limite, sans attribuer automatiquement tout changement à une cause unique.']],
 [['Indicateur','Relation','Résultat'],[['Valeur ajoutée simplifiée','360 000 − 144 000','216 000 €'],['Croissance en valeur','360 000 / 300 000 − 1','20 %'],['Indice de volume','120 / 108 × 100','111,11'],['Croissance en volume','111,11 − 100','11,11 % environ']]],[
 q('Atelier production : valeur ajoutée avec 360 000 € produits et 144 000 € de consommations intermédiaires ?', ['216 000 €.','504 000 €.','144 000 €.','360 000 €.'],'Dans le schéma donné, on retire les consommations intermédiaires de la production.',['L’addition ne mesure pas la création propre.','Ce montant représente les consommations intermédiaires.','La production inclut la valeur des éléments consommés.']),
 q('La production en valeur passe de 300 000 à 360 000 €. Quel taux ?', ['20 %.','16,67 %.','60 %.','120 %.'],'La variation vaut 60 000 / 300 000 = 20 %.',['Cette valeur prend la valeur finale comme base.','60 000 € n’est pas un taux de 60 %.','120 % est le niveau final rapporté au niveau initial, pas sa hausse.']),
 q('Indice de valeur 120 et indice des prix 108, même base 100 : indice de volume ?', ['111,11 environ.','12.','228.','108.'],'On divise les indices et on rétablit la base : 120 / 108 × 100.',['La différence des indices n’est pas le volume.','L’addition ne neutralise pas les prix.','108 est l’indice des prix donné.']),
 q('L’atelier permet-il de conclure directement sur la productivité horaire ?', ['Non, la quantité de travail n’est pas donnée.','Oui, elle augmente nécessairement de 20 %.','Oui, la valeur ajoutée suffit.','Oui, le prix fournit le nombre d’heures.'],'La productivité horaire rapporte une production à des heures de travail sur un périmètre cohérent.',['La croissance en valeur mélange d’autres effets.','La valeur ajoutée ne fournit pas seule le dénominateur horaire.','Un indice de prix ne mesure pas le temps de travail.'])
 ],[
 card('Production : valeur ajoutée et bénéfice sont-ils synonymes ?','Non. La valeur ajoutée mesure une contribution productive dans le cadre retenu.','360 000 − 144 000 = 216 000 € de valeur ajoutée simplifiée.','Ne pas y lire automatiquement le bénéfice net.'),
 card('Indices base 100 : comment passer de la valeur au volume ?','Indice de volume = indice de valeur / indice des prix × 100, si les périmètres sont cohérents.','120 / 108 × 100 ≈ 111,11.','Soustraire les taux est seulement une approximation éventuelle.'),
 card('Croissance : quelle valeur sert de base au taux de variation ?','La valeur initiale de l’indicateur comparé.','De 300 000 à 360 000 : +20 %.','Ne pas remplacer la base initiale par la valeur finale.'),
 card('Productivité horaire : quelle donnée manque à une production seule ?','La quantité d’heures de travail mobilisées sur le même périmètre.','Production / heures est une relation différente de la croissance en valeur.','Ne pas déduire une productivité d’un prix.')
 ],[['Valeur ajoutée, Insee','https://www.insee.fr/fr/metadonnees/definition/c2334']]),
 UE6:workshop('investissement','Une VAN positive, sous quelles hypothèses ?',
 'Atelier original. Investissement de 10 000 € à la date 0. Flux nets de projet de 6 000 € en fin d’année 1 et 6 000 € en fin d’année 2. Taux d’actualisation donné : 10 %. Pas de flux terminal, de BFR ni de flux supplémentaire.',[
 ['Mettre les flux sur une chronologie','La dépense initiale est à la date 0 ; elle n’est pas actualisée une seconde fois. Chaque flux futur doit être ramené à cette même date. Additionner les encaissements donne 12 000 €, mais ce total ne tient pas compte du temps ni du taux exigé dans l’exercice.','Les 6 000 € sont des flux nets fournis, pas un chiffre d’affaires à retraiter arbitrairement. Gardez le périmètre décrit et n’ajoutez pas une valeur de revente absente. Dans un autre dossier, l’impôt, le BFR, la récupération finale et les flux de financement doivent être examinés dans leur cadre propre.'],
 ['Du critère au jugement','La valeur actuelle des flux est 6 000 / 1,10 + 6 000 / 1,10² = 10 413,22 € environ. La VAN est donc 413,22 €. Le projet satisfait le critère VAN au taux et dans le scénario donnés.','Ce résultat ne promet pas les flux futurs et ne garantit pas que la trésorerie permettra l’investissement. Une réponse complète distingue le calcul, le critère financier et les autres contraintes. Une petite VAN positive appelle notamment une attention aux hypothèses plutôt qu’une certitude enthousiaste.']],
 [['Date','Flux fourni','Valeur à la date 0'],[['0','−10 000 €','−10 000 €'],['1','6 000 €','5 454,55 €'],['2','6 000 €','4 958,68 €'],['VAN','Somme des valeurs actuelles','413,22 € environ, calcul sans arrondis intermédiaires']]],[
 q('Atelier VAN : quelle expression respecte les dates des flux ?', ['−10 000 + 6 000 / 1,10 + 6 000 / 1,10².','−10 000 + 6 000 + 6 000.','−10 000 / 1,10 + 12 000.','−10 000 + 12 000 / 1,10².'],'Chaque flux futur est actualisé selon sa propre échéance ; le flux initial reste à la date 0.',['Cela ignore l’actualisation.','Cela déplace arbitrairement la dépense initiale.','Cela place tous les flux futurs à la fin de l’année 2.']),
 q('Quelle VAN obtient-on dans cet atelier, arrondie à deux décimales ?', ['413,22 €.','2 000 €.','−413,22 €.','10 413,22 €.'],'6 000 / 1,10 + 6 000 / 1,21 − 10 000 = 413,223… €.',['2 000 € est la somme non actualisée nette.','Le signe a été inversé.','Ce montant est la valeur actuelle des encaissements avant la dépense initiale.']),
 q('La VAN de 413,22 € démontre quoi dans cet atelier ?', ['Un excédent de valeur actualisée dans le scénario donné.','Une garantie des flux futurs.','Une trésorerie disponible de 413,22 € à la date 0.','Une absence de risque.'],'La VAN est un critère construit avec des flux et un taux donnés ; elle ne constitue ni garantie ni solde bancaire.',['Les flux fournis sont des hypothèses.','Valeur actualisée et encaissement immédiat sont distincts.','Le modèle n’élimine pas l’incertitude.']),
 q('Si les flux nets sont déjà fournis, quelle pratique éviter ?', ['Ajouter une revente non indiquée pour rendre la VAN positive.','Conserver les dates indiquées.','Utiliser le taux fourni.','Signaler les limites du scénario.'],'Les calculs doivent rester dans les hypothèses, même si une donnée inventée améliorerait le résultat.',['La chronologie est nécessaire.','Le taux donné définit le calcul demandé.','La discussion des limites est pertinente.'])
 ],[
 card('VAN : comment traiter le décaissement à la date 0 ?','Il entre avec son signe dans la somme sans nouvelle actualisation.','VAN = −I₀ + somme des flux futurs actualisés.','Ne pas déplacer le flux initial en année 1.'),
 card('Actualisation : deux flux à des dates différentes ont-ils le même facteur ?','Non, l’exposant reflète chaque échéance.','6 000 en année 1 se divise par 1,10 ; en année 2 par 1,10².','Ne pas actualiser tout le total à la dernière date.'),
 card('VAN positive : quelle réserve accompagner la conclusion ?','Le critère est satisfait sous les hypothèses de flux et de taux retenues.','Une VAN de 413,22 € reste sensible au scénario.','Ce n’est pas une garantie de résultat futur.'),
 card('Projet : valeur financière et liquidité sont-elles la même question ?','Non. Une décision peut satisfaire un critère de valeur et rencontrer une contrainte de financement.','La dépense de 10 000 € doit pouvoir être financée.','La VAN n’est pas un solde bancaire disponible.')
 ],[S.finance]),
 UE7:workshop('diagnostic-strategique','Du diagnostic à une recommandation',
 'Atelier original. Une PME dispose d’une équipe reconnue pour sa qualité, mais dépend d’une seule personne pour les devis. La demande progresse sur son marché. Un concurrent propose désormais une livraison plus rapide.',[
 ['Classer sans réciter','Le diagnostic interne porte sur les ressources et capacités de l’organisation ; le diagnostic externe sur son environnement. La qualité reconnue de l’équipe et la dépendance dans les devis décrivent des éléments internes. La demande et l’offre concurrente renseignent le contexte externe.','Un même fait peut avoir plusieurs implications, mais il faut justifier la catégorie utilisée. La dépendance envers une personne n’est pas une faiblesse parce que son nom figure dans une matrice ; c’est un risque de continuité et de capacité si l’activité dépend effectivement de sa disponibilité.'],
 ['Construire un lien entre observation et action','Une recommandation utile relie problème, action et contrôle. Former une seconde personne et documenter le processus de devis peut traiter la dépendance observée. Il faut prévoir temps, responsable et critère de résultat plutôt que réclamer une transformation générale sans moyens.','Le délai de devis et le taux d’erreurs doivent être suivis ensemble : accélérer tout en produisant des offres incorrectes déplacerait le problème. Le dossier n’établit pas que la seule vitesse de livraison explique le choix des clients. Recommandez une vérification plutôt que d’inventer une causalité.']],
 [['Fait','Lecture du diagnostic','Piste à vérifier'],[['Qualité reconnue','Force interne','Maintenir la qualité'],['Un seul rédacteur de devis','Fragilité interne','Former un relais'],['Demande en hausse','Opportunité externe','Capacité à servir'],['Concurrent plus rapide','Pression externe','Attentes des clients']]],[
 q('Atelier PME : la dépendance à une seule personne pour les devis relève de quel axe ?', ['Une fragilité interne.','Une opportunité externe.','Un taux d’inflation.','Une preuve de faillite certaine.'],'Le fait décrit l’organisation de la capacité interne et son risque de continuité.',['Ce n’est pas une évolution du marché.','Aucun indice de prix n’est donné.','Le dossier ne permet pas une conclusion aussi absolue.']),
 q('La progression de la demande sur le marché est principalement quoi dans cet atelier ?', ['Un élément de l’environnement externe.','Un compte de charge.','Une compétence automatiquement acquise.','Un bénéfice déjà encaissé.'],'La demande du marché décrit une évolution externe ; sa conversion en activité dépend des moyens de la PME.',['Il s’agit d’une observation de marché.','Une opportunité ne crée pas à elle seule une compétence.','Demande et encaissement sont distincts.']),
 q('Quelle action traite directement la dépendance dans la réalisation des devis ?', ['Documenter le processus et former un relais.','Changer uniquement la couleur du logo.','Supprimer toute vérification des devis.','Annoncer que la demande ne peut plus varier.'],'L’action cible le risque identifié en élargissant la capacité et la continuité.',['Cela ne traite pas la dépendance décrite.','La vitesse ne doit pas supprimer les contrôles utiles.','L’entreprise ne maîtrise pas cette évolution externe.']),
 q('Quel suivi limite un effet pervers d’un objectif de devis plus rapides ?', ['Délai de traitement et taux d’erreurs.','Délai seul dans tous les cas.','Nombre de logos créés.','Capital social seulement.'],'La qualité doit être suivie avec la rapidité pour éviter de déplacer le problème.',['Un délai réduit peut masquer des erreurs.','Cette mesure n’éclaire pas le processus de devis.','Le capital ne mesure pas directement cette qualité opérationnelle.'])
 ],[
 card('Diagnostic stratégique : comment distinguer interne et externe ?','Interne : ressources et capacités ; externe : environnement de l’organisation.','Une équipe compétente est interne ; la demande du marché est externe.','Ne pas classer par vocabulaire sans justifier le fait.'),
 card('Recommandation de management : quels liens rendre explicites ?','Fait, problème, action, moyens et contrôle du résultat.','Former un relais répond à une dépendance organisationnelle observée.','Une action générale sans lien avec le diagnostic est peu défendable.'),
 card('Objectif de rapidité : quel contre-indicateur peut être utile ?','Un indicateur de qualité ou d’erreurs sur le même processus.','Suivre temps de devis et corrections nécessaires.','Accélérer ne signifie pas améliorer sur tous les critères.'),
 card('Observation concurrentielle : pourquoi discuter la causalité ?','Le dossier peut montrer une différence sans établir ce qui cause les décisions des clients.','Livraison plus rapide ne prouve pas seule tous les choix de marché.','Ne pas transformer une hypothèse en cause démontrée.')
 ]),
 UE8:workshop('requetes','Tester une jointure sur trois clients',
 'Atelier original. CLIENT contient les identifiants 10, 20 et 30. FACTURE contient (A, 10, 100), (B, 10, 200), (C, 20, 80) : identifiant de facture, client et montant HT. Le besoin est d’afficher tous les clients avec le nombre de factures et le total, y compris les clients sans facture.',[
 ['Le besoin détermine la jointure','Le client 10 possède deux factures ; le client 20 en possède une ; le client 30 aucune. Une jointure interne ne conserve pas ce dernier dans ce jeu. Une jointure externe gauche depuis CLIENT peut conserver les trois clients. La présence d’une ligne sans facture ne doit pas être confondue avec une facture de montant nul.','La relation utilise la clé du client et la référence de client dans FACTURE. Les montants de 100 et 200 ne servent pas de clé. Vérifiez l’unicité des identifiants et l’intégrité de la référence avant d’interpréter un total.'],
 ['Compter et sommer les bons objets','Dans la ligne issue d’une jointure externe pour le client 30, COUNT(*) compterait la ligne du résultat, alors que COUNT(F.id) compte les identifiants de facture non NULL. Le besoin impose ici de compter les factures : le résultat attendu est donc zéro pour ce client.','SUM peut retourner NULL en l’absence de montant à sommer dans ce groupe. COALESCE(SUM(F.montant_ht), 0) permet d’afficher zéro selon le besoin. Cette présentation ne doit pas masquer les anomalies de données : une vraie facture avec un montant manquant reste une question à contrôler.']],
 [['Client','Nombre de factures attendu','Total HT attendu'],[['10','2','300 €'],['20','1','80 €'],['30','0','0 €']]],[
 q('Atelier jointure : quel total HT concerne le client 10 ?', ['300 €.','200 €.','380 €.','100 €.'],'Le client 10 est rattaché aux factures A et B : 100 + 200 = 300.',['Cela ignore la facture A.','380 est le total de tous les clients facturés.','Cela ignore la facture B.']),
 q('Quel type de jointure convient pour conserver ici tous les clients ?', ['CLIENT LEFT JOIN FACTURE.','CLIENT INNER JOIN FACTURE uniquement.','Un produit cartésien sans condition.','Une jointure sur le montant HT.'],'La jointure gauche conserve les lignes de CLIENT même sans correspondance en FACTURE.',['Le client 30 serait absent avec une jointure interne.','Le produit cartésien multiplie les combinaisons sans relier correctement les clients.','Un montant n’identifie pas le client.']),
 q('Pour le client sans facture après jointure gauche, quel comptage répond au besoin ?', ['COUNT(F.id) avec un identifiant de facture non NULL.','COUNT(*) comme nombre de factures.','SUM(C.id).','COUNT du nom de client comme facture.'],'COUNT(F.id) ne compte pas l’absence de facture matérialisée par NULL.',['COUNT(*) compterait la ligne conservée.','Additionner des identifiants ne compte pas les factures.','Le client conservé n’est pas une facture.']),
 q('Pourquoi utiliser COALESCE(SUM(F.montant_ht), 0) dans ce besoin ?', ['Afficher zéro quand la somme du groupe est NULL faute de facture.','Créer une facture fictive.','Doubler les montants du client.','Garantir que toutes les données sont correctes.'],'La fonction règle ici la présentation d’une valeur absente ; elle ne crée pas de nouvelle opération.',['Le résultat d’affichage ne crée aucun document.','Cette expression ne multiplie pas la somme.','Le contrôle des anomalies reste nécessaire.'])
 ],[
 card('Jointure : quel côté conserve un LEFT JOIN ?','Les lignes de la table à gauche, même sans correspondance à droite.','CLIENT LEFT JOIN FACTURE conserve un client sans facture.','Une jointure interne ne répond pas au même besoin.'),
 card('COUNT(*) et COUNT(F.id) : pourquoi peuvent-ils différer ?','COUNT(*) compte les lignes ; COUNT(F.id) compte les valeurs non NULL de ce champ.','Un client conservé sans facture peut donner 1 ligne mais 0 identifiant de facture.','Le nombre de lignes du résultat n’est pas toujours le nombre d’opérations.'),
 card('Agrégat absent : à quoi sert COALESCE dans un affichage ?','Choisir une valeur de remplacement lorsque l’expression est NULL.','COALESCE(SUM(montant_ht), 0) peut afficher zéro sans facture.','Ne pas en faire une preuve de qualité des données.'),
 card('Requête métier : quel jeu de test minimum préparer ?','Cas ordinaire, plusieurs opérations par entité et entité sans opération.','Clients 10 avec deux factures, 20 avec une et 30 sans facture.','Tester uniquement un client facturé masque le problème de jointure.')
 ]),
 UE9:workshop('operations','Achat à crédit puis règlement',
 'Atelier original. Achat de marchandises de 1 000 € HT, TVA déductible de 200 € selon les hypothèses, facture fournisseur de 1 200 € TTC. La facture est enregistrée puis réglée intégralement par banque. Pas d’escompte ni d’autre frais.',[
 ['Deux événements, deux écritures','L’achat à crédit fait apparaître une charge, une taxe déductible et une dette fournisseur dans le schéma donné. Le règlement ultérieur éteint cette dette et diminue la banque. Il ne constitue pas un second achat et ne doit pas faire enregistrer une deuxième fois la charge.','Les montants HT, taxe et TTC ne se placent pas indistinctement dans le même compte. Ici, la TVA est déductible par hypothèse ; le coût porté en charge est donc le HT. Les références de compte ci-dessous correspondent aux catégories usuelles du PCG et restent à adapter au détail du plan utilisé.'],
 ['Contrôler au-delà de l’égalité','Chaque écriture équilibre débit et crédit. Après le règlement, la dette issue de cette facture est soldée. La trésorerie a baissé de 1 200 €, alors que la charge d’achat de ce schéma est de 1 000 €. Cette différence ne constitue pas une erreur : elle s’explique par la TVA.','L’équilibre arithmétique ne prouve pas que les bons comptes ont été choisis. Une écriture qui débiterait à nouveau les achats lors du paiement pourrait être équilibrée et pourtant fausse. Contrôlez la nature de l’événement, la pièce et le solde du fournisseur.']],
 [['Événement','Compte et objet','Débit','Crédit'],[['Facture','607 · Achats de marchandises','1 000 €',''],['Facture','44566 · TVA déductible sur autres biens et services','200 €',''],['Facture','401 · Fournisseur','','1 200 €'],['Règlement','401 · Fournisseur','1 200 €',''],['Règlement','512 · Banque','','1 200 €']]],[
 q('Atelier achat à crédit : quel montant crédite la dette fournisseur ?', ['1 200 €.','1 000 €.','200 €.','2 200 €.'],'Le fournisseur est dû du montant TTC : 1 000 + 200 = 1 200.',['Cela omet la taxe dans la dette.','Cela représente seulement la taxe.','Le HT n’est pas ajouté une seconde fois au TTC.']),
 q('Quelle écriture traduit le règlement de cette facture ?', ['Débit fournisseur 1 200 € ; crédit banque 1 200 €.','Débit achats 1 200 € ; crédit fournisseur 1 200 €.','Débit banque 1 200 € ; crédit fournisseur 1 200 €.','Débit TVA 1 200 € ; crédit banque 1 200 €.'],'Le paiement éteint la dette au débit du fournisseur et réduit la banque au crédit.',['Cela enregistrerait un nouvel achat au lieu de solder la dette.','Cela augmente la banque et la dette dans le sens contraire du règlement.','Le paiement TTC ne devient pas une nouvelle taxe déductible.']),
 q('Après règlement, quel solde reste sur la dette de cette facture seule ?', ['0 €.','1 200 € créditeurs.','1 000 € débiteurs.','200 € créditeurs.'],'La dette de 1 200 € a été créée au crédit puis entièrement apurée au débit.',['Cela ignore le règlement.','Ce montant ne correspond pas au solde de la dette.','La taxe fait partie du montant réglé.']),
 q('Dans cet achat, pourquoi la banque baisse-t-elle de 1 200 € alors que la charge vaut 1 000 € ?', ['La différence est la TVA déductible donnée.','La charge doit forcément être enregistrée deux fois.','La TVA est un bénéfice.','La dette fournisseur disparaît sans paiement.'],'Le TTC réglé comprend le HT porté en charge et la taxe déductible distincte.',['Le règlement n’est pas une deuxième charge.','La taxe déductible n’est pas un bénéfice.','Le dossier décrit un paiement effectif.'])
 ],[
 card('Achat à crédit : quelles composantes séparer dans la facture ?','Charge HT, TVA déductible selon les hypothèses et dette TTC.','1 000 + 200 = 1 200 € dus au fournisseur.','Ne pas porter indistinctement le TTC en charge si la taxe est déductible.'),
 card('Règlement fournisseur : quel effet comptable suivre ?','Extinction de la dette et diminution de la banque.','Débit 401 et crédit 512 pour 1 200 € dans cet atelier.','Ne pas enregistrer un second achat.'),
 card('Écriture équilibrée : que faut-il contrôler en plus ?','Nature de l’opération, comptes, pièce et période.','Une deuxième charge au paiement peut être équilibrée mais erronée.','L’égalité débit/crédit ne suffit pas à prouver la justesse.'),
 card('Charge et paiement : pourquoi les montants peuvent-ils différer ?','Le paiement peut comprendre une taxe déductible enregistrée séparément.','Charge de 1 000 €, paiement de 1 200 € ici.','Ne pas confondre résultat et flux de trésorerie.')
 ],[S.pcg]),
 UE10:workshop('evaluation','Acquisition : coût d’entrée et charge distincte',
 'Atelier original. Une machine coûte 20 000 €. Sa mise en place directement nécessaire coûte 1 000 €. Une formation du personnel distincte coûte 500 €. TVA récupérable exclue des montants, aucune autre composante. Machine utilisable au début de l’exercice, durée de cinq ans, valeur résiduelle nulle et amortissement linéaire.',[
 ['Le coût dépend du lien avec l’actif','Dans ce cadre simplifié, l’achat et la mise en place nécessaire constituent un coût d’entrée de 21 000 €. La formation distincte ne se transforme pas en coût de la machine parce qu’elle est utile à l’entreprise. Elle relève d’une dépense séparée dans les hypothèses de l’atelier.','Il faut examiner la nature et le lien de chaque dépense avec l’actif. Un montant élevé, une facture commune ou une date proche ne suffisent pas à justifier l’incorporation. Dans un dossier plus complet, les composants, la valeur résiduelle et les conditions de reconnaissance doivent être traités selon le référentiel applicable.'],
 ['Séparer évaluation et amortissement','La base amortissable donnée est 21 000 €, puisqu’aucune valeur résiduelle n’est retenue. La dotation annuelle linéaire vaut 4 200 €. L’actif étant utilisable dès le début de l’exercice, aucun prorata n’est nécessaire dans cet exemple.','La dépense de formation de 500 € ne doit pas être répartie arbitrairement sur les cinq années de vie de la machine. Justifiez chaque traitement séparément : coût retenu, charge distincte, base, durée, méthode et date de départ de l’utilisation.']],
 [['Élément','Traitement dans l’atelier','Montant'],[['Machine','Coût d’acquisition','20 000 €'],['Installation nécessaire','Coût directement attribuable','1 000 €'],['Formation distincte','Dépense séparée','500 €'],['Base amortissable','21 000 − 0','21 000 €'],['Dotation annuelle','21 000 / 5','4 200 €']]],[
 q('Atelier machine : quel coût d’entrée retenir selon les hypothèses ?', ['21 000 €.','21 500 €.','20 000 €.','1 500 €.'],'On retient l’achat et l’installation nécessaire : 20 000 + 1 000.',['La formation distincte a été incorporée à tort.','L’installation nécessaire a été omise.','Les dépenses accessoires ne remplacent pas le prix d’acquisition.']),
 q('Base amortissable 21 000 €, cinq ans, linéaire : dotation d’une année complète ?', ['4 200 €.','4 300 €.','21 000 €.','500 €.'],'La dotation est 21 000 / 5 = 4 200 €.',['Ce montant amortit aussi les 500 € de formation.','La base entière n’est pas la dotation annuelle.','500 € est la formation distincte.']),
 q('Pourquoi ne pas incorporer automatiquement la formation distincte ?', ['Son utilité ne suffit pas à en faire un coût de la machine.','Toute dépense proche de l’achat est incorporable.','La formation ne peut jamais être utile.','Une facture élevée change la durée à elle seule.'],'Il faut qualifier la dépense et le critère d’incorporation dans le référentiel.',['La proximité de date ne remplace pas les critères.','Utilité pour l’entreprise et traitement comptable sont deux questions.','Le montant de facture ne fixe pas seul la durée d’utilisation.']),
 q('Pourquoi n’applique-t-on pas de prorata dans cet atelier ?', ['La machine est utilisable dès le début de l’exercice donné.','Le prorata n’existe jamais.','La TVA est récupérable.','La formation coûte 500 €.'],'Le dossier donne une année complète d’utilisation ; une autre date demanderait son propre calcul.',['La conclusion dépend de la date, pas d’une interdiction générale.','La TVA n’explique pas la durée d’utilisation.','Le coût de formation ne détermine pas la date de départ.'])
 ],[
 card('Coût d’entrée : quel critère remplacerait une simple proximité de date ?','Le lien de la dépense avec l’acquisition et la mise en état d’utilisation selon le référentiel.','Installation nécessaire de 1 000 € retenue ; formation distincte de 500 € séparée ici.','Utile à l’entreprise ne signifie pas automatiquement incorporable.'),
 card('Amortissement linéaire : quelle base répartir ?','Le montant amortissable, notamment après déduction de la valeur résiduelle retenue.','21 000 € et valeur résiduelle nulle donnent 4 200 € par an sur cinq ans.','Ne pas inclure arbitrairement une charge distincte.'),
 card('Dotation : quelle date faut-il examiner ?','Le début de l’utilisation ou de la consommation des avantages selon le cadre.','Une année complète est donnée dans cet atelier.','La date de paiement ne fixe pas automatiquement le prorata.'),
 card('Évaluation d’un actif : quels choix documenter ensemble ?','Reconnaissance, coût, composants éventuels, base, durée, méthode et date.','Le résultat chiffré doit être relié à ces hypothèses.','Un calcul juste peut reposer sur une base incorrecte.')
 ],[S.pcg]),
 UE11:workshop('rentabilite','Seuil en quantité : vérifier le modèle',
 'Atelier original. Prix unitaire 80 €, coût variable unitaire 50 €, charges fixes de période 24 000 €. Hypothèse de modèle : un seul produit, prix et coût variable constants, toute la production vendue. Volume étudié : 1 000 unités.',[
 ['La marge finance les charges fixes','Une unité vendue apporte 80 − 50 = 30 € de marge sur coût variable. Cette marge n’est pas un résultat net unitaire : elle contribue d’abord à couvrir les charges fixes du périmètre. Le seuil en quantité est 24 000 / 30 = 800 unités.','À 1 000 unités, la marge totale atteint 30 000 €. Le résultat du modèle est 30 000 − 24 000 = 6 000 €. Il s’agit du résultat de ce périmètre simplifié, sans inventer impôt, financement ou autres charges absentes du dossier.'],
 ['Discuter la marge de sécurité','Le volume peut baisser de 200 unités jusqu’au seuil, soit 20 % des 1 000 unités actuelles. Ce taux mesure une distance au seuil dans le modèle ; il ne constitue pas une garantie contre les changements de prix, de mix ou de coûts.','Si la marge unitaire devenait nulle ou négative, la division utilisée ici ne fournirait pas un seuil positif économiquement exploitable. Si plusieurs produits sont vendus, il faut préciser le mix. Une formule ne doit pas être appliquée à des données qui ne respectent plus ses hypothèses.']],
 [['Indicateur','Calcul','Résultat'],[['Marge unitaire','80 − 50','30 €/unité'],['Seuil en quantité','24 000 / 30','800 unités'],['Résultat à 1 000 unités','1 000 × 30 − 24 000','6 000 €'],['Sécurité en volume','1 000 − 800','200 unités, soit 20 %']]],[
 q('Atelier seuil : quelle marge unitaire résulte du prix 80 € et du coût variable 50 € ?', ['30 €.','130 €.','50 €.','80 €.'],'La marge unitaire sur coût variable est le prix diminué du coût variable unitaire.',['L’addition ne mesure pas une marge.','50 € est le coût variable donné.','80 € est le prix avant déduction.']),
 q('Charges fixes 24 000 € et marge unitaire 30 € : seuil en quantité ?', ['800 unités.','300 unités.','480 unités.','24 030 unités.'],'24 000 / 30 = 800 unités ; à ce volume, la marge couvre les charges fixes.',['Cela divise par le prix plutôt que par la marge.','Cela divise par le coût variable.','Additionner une charge totale et une marge unitaire ne donne pas une quantité.']),
 q('Quel résultat donne le modèle à 1 000 unités ?', ['6 000 €.','30 000 €.','80 000 €.','−6 000 €.'],'1 000 × (80 − 50) − 24 000 = 6 000 €.',['La marge totale n’est pas encore diminuée des charges fixes.','Le chiffre d’affaires n’est pas le résultat.','Le signe est inversé par rapport au calcul.']),
 q('Dans cet atelier, quel taux de marge de sécurité en volume retenir ?', ['20 % du volume actuel.','25 % du volume actuel.','80 % du volume actuel.','200 % du volume actuel.'],'La distance au seuil est 200 unités, rapportée à 1 000 : 20 %.',['25 % rapporte la distance au seuil de 800, pas au volume actuel.','80 % est le seuil rapporté au volume actuel.','200 unités ne constituent pas un taux de 200 %.'])
 ],[
 card('Seuil en quantité : quelle relation utiliser dans le modèle à un produit ?','Charges fixes / marge unitaire sur coût variable, si cette marge est positive.','24 000 / 30 = 800 unités.','Vérifier prix, coûts, périmètre et hypothèse de volume vendu.'),
 card('Marge unitaire : pourquoi ne pas l’appeler résultat net unitaire ?','Elle contribue d’abord à couvrir les charges fixes du périmètre.','30 € par unité puis 24 000 € de charges fixes à absorber.','Ne pas oublier les charges fixes dans le résultat total.'),
 card('Marge de sécurité : quelle base prendre pour son taux usuel ?','Le niveau actuel d’activité comparé au seuil, sur une unité cohérente.','(1 000 − 800) / 1 000 = 20 %.','Ne pas mélanger unités, euros et pourcentages.'),
 card('Seuil : quel changement oblige à revoir le modèle ?','Un changement de prix, coût, périmètre ou mix de produits.','Plusieurs produits exigent une hypothèse de mix.','La distance au seuil n’est pas une assurance contre tous les risques.')
 ]),
 UE12:workshop('donnees','Revenue rose, profit fell',
 'Original practice. A company reports revenue of €120 million in Year 1 and €132 million in Year 2. Profit moves from €12 million to €10 million. The document does not explain the causes and gives no cash-flow forecast.',[
 ['Keep the measures separate','Revenue rose by €12 million, or 10% of the Year 1 figure. Profit fell by €2 million, or approximately 16.67%. A sentence saying that “the company grew by 10%” is vague because it does not name the measure. Say what changed, over which period and by how much.','Revenue is not profit, and profit is not automatically cash flow. Use the vocabulary of the document rather than translating every French occurrence of chiffre as figure. In this exercise, both series are expressed in millions of euros; retain that unit when writing your summary.'],
 ['Evidence before explanation','A defensible summary is: “Revenue increased by 10%, while profit fell by about 16.67%.” While makes the contrast explicit. The fall in profit does not prove that the increase in revenue caused it. Costs, margins or other factors would require evidence from the document.','Use the past tense for the reported periods. Do not present a forecast as an observed result, or promise a recovery without supporting information. A clear professional message separates what the figures show from what the reader should investigate next.']],
 [['Measure','Year 1','Year 2','Change'],[['Revenue','€120m','€132m','+10%'],['Profit','€12m','€10m','About −16.67%'],['Cash flow','Not provided','Not provided','Cannot be calculated here']]],[
 q('Business English workshop: revenue moves from €120m to €132m. Which statement is accurate?', ['Revenue increased by 10%.','Revenue increased by 12%.','Profit increased by 10%.','Revenue increased by 110%.'],'The increase is €12m divided by the initial €120m: 10%.',['€12m is an amount, not a rate of 12%.','The profit figures describe a different measure.','110% is the final level relative to the initial level, not its increase.']),
 q('Profit moves from €12m to €10m. Which description fits the figures?', ['Profit fell by about 16.67%.','Profit rose by 20%.','Profit fell by €10m.','Revenue fell by 16.67%.'],'The fall is €2m / €12m, about 16.67%.',['This reverses the direction and uses the wrong base.','€10m is the final profit, not the fall.','Revenue is a separate increasing series.']),
 q('Which connector clearly contrasts the reported revenue and profit trends?', ['While.','Because, to prove causation from these figures alone.','Therefore, to guarantee recovery.','Including, to express a time period.'],'“Revenue increased, while profit fell” states a contrast without inventing causation.',['The document does not establish causation.','No recovery is established.','Including does not express this contrast or time relation.']),
 q('Which claim goes beyond the evidence in this workshop?', ['Higher revenue caused the fall in profit.','Revenue rose from €120m to €132m.','Profit fell from €12m to €10m.','The document gives no cash-flow forecast.'],'The figures show two changes, not the cause of one change.',['This is given in the document.','This is also given.','This correctly describes a missing item.'])
 ],[
 card('Business English: revenue, profit and cash flow?','Revenue relates to sales activity; profit is an accounting result; cash flow concerns cash movements.','Revenue may rise while profit falls.','Do not use the three terms interchangeably.'),
 card('Trend writing: what is the difference between by and to?','By introduces the amount of change; to introduces the final level.','Revenue rose by €12m to €132m.','The final amount is not the amount of increase.'),
 card('Contrast in a financial summary: how can while be used?','It can connect two contrasting observations without claiming a causal link.','Revenue increased, while profit declined.','Do not replace a contrast with an unsupported because.'),
 card('Financial figures in English: what makes a summary precise?','The measure, period, unit, direction and amount or rate of change.','Profit fell from €12m to €10m.','A vague claim that the company grew hides the indicator.')
 ]),
 UE13:workshop('rapport','De la mission à l’analyse du résultat',
 'Atelier original. Pendant une mission, l’élève observe un traitement moyen de 20 minutes sur 30 dossiers, puis 15 minutes sur 30 autres dossiers après l’introduction d’une liste de contrôle. La composition des deux lots et le taux d’erreurs ne sont pas précisés.',[
 ['Décrire la contribution personnelle','Le rapport doit distinguer contexte de la mission, travail réellement réalisé et éléments analysés. Le passage de 20 à 15 minutes décrit une baisse du temps moyen de 25 % dans les lots observés. Il ne justifie pas automatiquement une affirmation de productivité globale ni une amélioration pour tous les dossiers de l’entreprise.','L’élève peut expliquer la préparation de la liste, les échanges avec l’équipe et le mode de mesure, si ces actions correspondent à son travail. Il ne doit pas s’attribuer seul une décision collective ni transformer une contribution en réalisation fictive.'],
 ['Discuter l’effet de l’amélioration','Une comparaison avant/après ne démontre pas seule que la liste a causé tout le changement. Complexité des dossiers, expérience de l’équipe ou méthode de chronométrage peuvent différer. Le taux d’erreurs est également nécessaire pour ne pas réduire la qualité au temps de traitement.','Un passage analytique peut présenter le résultat, les limites puis une proposition de suivi : lot comparable, définition du début et de la fin, erreurs et reprises. Les annexes documentent la démarche ; elles ne remplacent pas son explication dans le corps du rapport.']],
 [['Partie du rapport','Contenu utile','Limite à signaler'],[['Mission','Liste de contrôle et rôle personnel','Ne pas s’attribuer les actions d’autrui'],['Résultat observé','20 à 15 minutes, baisse de 25 %','Lots non comparés en complexité'],['Discussion','Temps, erreurs et reprises','Causalité non établie par la seule comparaison']]],[
 q('Atelier rapport : de 20 à 15 minutes, quelle baisse du temps moyen ?', ['25 %.','33,33 %.','5 %.','75 %.'],'La baisse est 5 / 20 = 25 %.',['Cette valeur rapporte l’écart au temps final.','5 minutes ne signifient pas une baisse de 5 %.','75 % est le niveau restant rapporté au niveau initial.']),
 q('Quel énoncé distingue observation et causalité ?', ['Le temps observé baisse ; la cause complète reste à examiner.','La liste prouve seule toute la causalité.','Toutes les missions gagnent forcément 25 %.','Le taux d’erreurs est nécessairement nul.'],'Les deux lots ne sont pas décrits comme comparables sur tous les facteurs.',['Une comparaison seule ne neutralise pas les autres facteurs.','Le résultat local ne vaut pas pour toute mission.','Cette donnée n’est pas fournie.']),
 q('Que faut-il préciser pour présenter la contribution personnelle ?', ['Les actions réellement menées et le rôle dans le travail collectif.','Un résultat supérieur inventé.','Toute la décision attribuée à l’élève sans preuve.','Uniquement le nom de l’entreprise.'],'L’analyse doit rendre la contribution identifiable et fidèle aux faits.',['Cela déforme l’expérience.','La décision collective ne doit pas être appropriée sans justification.','Le contexte seul ne décrit pas le travail.']),
 q('Quel suivi compléterait utilement le temps de traitement ?', ['Erreurs et reprises sur des dossiers comparables.','La couleur des annexes seulement.','Le nombre de pages comme qualité opérationnelle.','L’absence de mesure après la mission.'],'Temps et qualité doivent être rapprochés sur un périmètre comparable.',['La présentation n’évalue pas ce processus.','La pagination ne mesure pas les erreurs du traitement.','Sans mesure, l’effet est plus difficile à discuter.'])
 ],[
 card('Rapport professionnel : description et analyse se distinguent comment ?','La description expose la mission ; l’analyse explique les méthodes, résultats et limites.','Une liste de contrôle devient un objet d’analyse par son usage et ses effets documentés.','Ne pas remplacer le raisonnement par un récit chronologique seul.'),
 card('Avant/après : pourquoi parler de comparabilité ?','Les changements de contexte peuvent affecter le résultat observé.','Deux lots de 30 dossiers n’ont pas nécessairement la même complexité.','Même effectif ne signifie pas mêmes conditions.'),
 card('Contribution personnelle : quelle exigence respecter ?','Décrire fidèlement son rôle et distinguer les actions collectives.','Préparer une liste et participer à un test ne signifie pas avoir décidé seul du projet.','Ne pas inventer une mission pour enrichir le rapport.'),
 card('Annexe : quel rôle doit-elle jouer dans une démonstration ?','Documenter un élément analysé dans le corps du rapport.','Un relevé des temps soutient une comparaison expliquée.','Ne pas demander au lecteur de construire lui-même toute l’analyse.')
 ]),
 DSCG1:workshop('diagnostic','Revue d’acquisition : séparer les angles',
 'Atelier original. Un acquéreur reçoit les comptes d’une société cible, une liste de contrats et un courriel signalant un litige social. Aucun dossier détaillé du litige ni clause de garantie finalisée n’est fourni.',[
 ['Construire une carte des vérifications','Les comptes, les contrats et le signalement social correspondent à des sources différentes. Les comptes peuvent contenir un traitement comptable du risque, mais ne remplacent pas les actes et échanges nécessaires à son analyse juridique. Le courriel identifie une question à investiguer, sans déterminer seul son issue ou son montant.','Pour chaque point, notez le fait, le régime à examiner, la pièce manquante et la conséquence possible. Gardez séparés le risque de la cible, l’effet sur la négociation du prix et la répartition contractuelle du risque entre vendeur et acquéreur.'],
 ['Recommander avec des conditions','Une clause de garantie ne doit pas être supposée définitive parce que les parties discutent d’une acquisition. Son objet, ses exclusions, sa durée et ses modalités demandent examen. Une négociation de prix ne fait pas disparaître par elle-même le litige social.','Une recommandation peut proposer d’obtenir le dossier du litige, de vérifier le traitement comptable et de faire examiner les mécanismes contractuels pertinents. Elle précise responsable et condition avant signature. Évitez d’annoncer qu’une garantie couvrira nécessairement tout risque, indépendamment de son contenu.']],
 [['Source','Question','Pièce ou contrôle attendu'],[['Comptes','Traitement du risque','Justification comptable et données de base'],['Contrats','Engagements et conditions','Actes et annexes pertinents'],['Courriel social','Nature et stade du litige','Dossier, demandes et réponses'],['Projet de garantie','Répartition du risque','Clause et conditions définitives']]],[
 q('Atelier acquisition : le courriel signalant un litige suffit-il à chiffrer sa perte certaine ?', ['Non, il ouvre une vérification.','Oui, tout signalement est une condamnation.','Oui, le montant doit être inventé.','Oui, si la cible est rentable.'],'Il manque notamment les faits, demandes, pièces et stade du litige.',['Signalement et décision définitive sont distincts.','Le chiffrage ne doit pas être fabriqué.','La rentabilité ne décrit pas les conditions du litige.']),
 q('Quel contrôle croise utilement l’angle juridique et l’angle comptable ?', ['Comparer le dossier du litige au traitement dans les comptes.','Lire seulement le nom de la cible.','Écarter toutes les pièces juridiques.','Transformer le prix demandé en perte sociale.'],'Les deux angles se rapprochent sans être confondus.',['Le nom ne documente pas le risque.','Le traitement comptable ne remplace pas toutes les pièces.','Prix et risque social sont des objets distincts.']),
 q('Une garantie d’acquisition en discussion couvre-t-elle nécessairement tout risque ?', ['Non, son contenu et ses conditions sont à examiner.','Oui, son titre suffit.','Oui, même sans clause finalisée.','Oui, elle efface le litige de la cible.'],'Il faut examiner objet, périmètre, exclusions et modalités du mécanisme retenu.',['Le titre de la clause ne définit pas toute sa portée.','Le dossier dit que la clause n’est pas finalisée.','Répartir un risque ne supprime pas automatiquement le fait litigieux.']),
 q('Quelle recommandation est proportionnée au dossier d’acquisition ?', ['Obtenir les pièces du litige et examiner les conséquences avant signature.','Garantir sans pièces l’absence de risque.','Conclure à une condamnation certaine.','Ignorer le sujet car les comptes existent.'],'La recommandation relie incertitude, contrôle et étape de décision.',['L’absence de pièces ne justifie pas cette garantie.','Le signalement ne donne pas une décision certaine.','Les comptes ne rendent pas inutile l’examen du litige.'])
 ],[
 card('Diagnostic transversal : pourquoi distinguer les angles ?','Juridique, fiscal, social et comptable mobilisent des règles et pièces différentes.','Un risque social peut avoir aussi une traduction comptable.','Croiser les conclusions ne signifie pas fusionner les régimes.'),
 card('Acquisition : quel tableau aide à prioriser les risques ?','Fait, source, régime, impact possible, pièce manquante et action.','Le courriel d’alerte mène à une demande du dossier de litige.','Une information partielle n’est pas une perte certaine.'),
 card('Garantie d’acquisition : quels éléments en fixent la portée ?','Objet, périmètre, conditions, exclusions et modalités applicables.','La clause doit être examinée dans sa version pertinente.','Le mot garantie ne promet pas une couverture universelle.'),
 card('Recommandation juridique : comment traiter une incertitude ?','Nommer le contrôle, l’information attendue et la condition de décision.','Vérifier le dossier du litige avant de conclure sur l’acquisition.','Ne pas inventer un fait pour rendre la recommandation définitive.')
 ],[S.civil]),
 DSCG2:workshop('valorisation','DCF : valeur terminale et valeur des actions',
 'Atelier original. Flux disponible pour l’entreprise de 11 000 € en fin d’année 1 ; croissance stable donnée de 2 % à partir de l’année 2. CMPC donné : 10 %. Dette nette : 20 000 €. Nombre d’actions : 10 000. Aucune autre correction de valeur. Les hypothèses du modèle à croissance constante sont admises pour le calcul.',[
 ['Faire coïncider flux et taux','Le flux est destiné à l’ensemble des financeurs dans ce modèle ; le taux fourni est le coût moyen pondéré du capital. Un flux destiné aux seuls actionnaires appellerait un autre appariement. La cohérence ne se limite pas au nom du taux : devise, inflation, horizon et risque doivent être examinés dans un dossier complet.','La valeur terminale située en fin d’année 1 repose sur le flux de l’année 2 : 11 000 × 1,02 = 11 220 €. Elle vaut 11 220 / (0,10 − 0,02) = 140 250 €. Le dénominateur doit être positif dans ce modèle. Une croissance supérieure ou égale au taux ne produit pas une valeur exploitable par cette relation.'],
 ['Distinguer les droits valorisés','À la date 0, la valeur d’entreprise est (11 000 + 140 250) / 1,10 = 137 500 €. La dette nette donnée est ensuite retranchée : valeur des capitaux propres 117 500 €, soit 11,75 € par action. Ne retranchez pas la dette une seconde fois dans le flux déjà défini.','La valeur terminale représente une grande part du total. Ce résultat impose de discuter le taux, la croissance et la pérennité des flux. La valeur obtenue est une estimation conditionnelle, pas un cours futur garanti ni une recommandation d’investissement.']],
 [['Étage de valorisation','Calcul','Résultat'],[['Flux année 2','11 000 × 1,02','11 220 €'],['Valeur terminale à t1','11 220 / (10 % − 2 %)','140 250 €'],['Valeur d’entreprise à t0','(11 000 + 140 250) / 1,10','137 500 €'],['Capitaux propres','137 500 − 20 000','117 500 €'],['Par action','117 500 / 10 000','11,75 €']]],[
 q('Atelier DCF : quel flux sert au numérateur de la valeur terminale à t1 ?', ['11 220 €, flux de l’année 2.','11 000 €, sans croissance.','20 000 €, dette nette.','137 500 €, valeur d’entreprise.'],'La croissance stable commence à l’année 2 : 11 000 × 1,02 = 11 220.',['Cela omet la croissance fournie.','La dette n’est pas le flux opérationnel futur.','La valeur totale n’est pas un flux annuel.']),
 q('Dans cet atelier, quelle valeur terminale à t1 obtient-on ?', ['140 250 €.','112 200 €.','137 500 €.','1 402,50 €.'],'11 220 / (0,10 − 0,02) = 140 250.',['Cela divise par 10 % sans retrancher la croissance.','C’est la valeur d’entreprise actualisée à t0.','Le calcul traite mal les pourcentages du dénominateur.']),
 q('Valeur d’entreprise 137 500 €, dette nette 20 000 €, 10 000 actions : valeur par action ?', ['11,75 €.','13,75 €.','15,75 €.','1,175 €.'],'(137 500 − 20 000) / 10 000 = 11,75.',['Cela ne retire pas la dette nette.','Cela ajoute la dette au lieu de la retirer.','Le nombre d’actions est appliqué avec un facteur erroné.']),
 q('Quelle condition est nécessaire pour utiliser ici la formule à croissance constante ?', ['Le taux d’actualisation est supérieur au taux de croissance.','Les deux taux sont toujours égaux.','La croissance peut dépasser le taux sans difficulté.','La valeur terminale ne dépend d’aucune hypothèse.'],'Un écart positif entre taux et croissance est nécessaire à cette relation dans le modèle donné.',['Le dénominateur serait nul.','Un dénominateur négatif ne donne pas une valorisation exploitable par ce modèle.','La valeur dépend fortement des hypothèses.'])
 ],[
 card('DCF d’entreprise : comment apparier flux et taux ?','Associer les flux destinés à l’ensemble des financeurs au taux cohérent de ce périmètre.','FCFF et CMPC dans le modèle décrit.','Ne pas mélanger avec un flux destiné aux seuls actionnaires.'),
 card('Valeur terminale constante : quel flux et quel dénominateur ?','Le flux de la période suivante, divisé par taux d’actualisation moins croissance, sous les hypothèses du modèle.','11 220 / (0,10 − 0,02) = 140 250 à t1.','Le taux doit être supérieur à la croissance dans ce modèle.'),
 card('Valeur d’entreprise : comment arriver aux capitaux propres avec la dette nette donnée ?','Retrancher la dette nette et les autres corrections pertinentes du dossier.','137 500 − 20 000 = 117 500 €.','Ne pas soustraire un élément déjà pris en compte ailleurs.'),
 card('DCF : pourquoi discuter une forte valeur terminale ?','Elle concentre la sensibilité aux hypothèses de long terme.','Un petit changement de croissance peut modifier fortement l’estimation.','Une estimation ne garantit pas un cours futur.')
 ],[S.finance]),
 DSCG3:workshop('pilotage','Quand l’indicateur déplace le problème',
 'Atelier original. Une équipe ferme 100 dossiers sur la période. Un contrôle identifie 15 dossiers rouverts pour erreur. La prime suit uniquement le nombre de clôtures. Le délai cible et les causes des erreurs ne sont pas encore étudiés.',[
 ['Distinguer résultat compté et objectif réel','Le nombre de dossiers clos mesure une activité, mais peut ne pas mesurer le service durablement rendu. Les 15 réouvertures rapportées aux 100 clôtures donnent un taux de 15 % dans ce périmètre. Il faut préciser si une réouverture est comptée une fois et si elle concerne la même population.','Un objectif de volume seul peut favoriser des clôtures précipitées. Ce mécanisme est un risque de comportement, pas une accusation prouvée contre l’équipe. Les causes possibles demandent des faits : formation, charge, complexité, outil, règles de contrôle ou incitations.'],
 ['Construire un tableau de bord équilibré','Associez volume, délai et qualité avec des définitions stables. Précisez source des données, fréquence de lecture et responsable de l’analyse. Une mesure sans seuil discuté ni action associée peut devenir une collection de nombres qui ne pilote rien.','La prime ne doit pas être modifiée mécaniquement à partir d’un seul signal. Examinez d’abord les objectifs contradictoires et la capacité de l’équipe à agir sur les causes. Une action de pilotage explique le diagnostic, le levier et la mesure qui permettra de vérifier son effet.']],
 [['Mesure','Définition dans l’atelier','Ce qu’il faut compléter'],[['Volume','100 clôtures','Dossiers réellement achevés'],['Qualité','15 réouvertures / 100 clôtures = 15 %','Causes et critères du contrôle'],['Délai','Non fourni','Population et point de départ'],['Incitation','Prime liée au volume seul','Effets sur les comportements']]],[
 q('Atelier pilotage : 15 réouvertures parmi 100 clôtures donnent quel taux ?', ['15 %.','85 %.','6,67 %.','115 %.'],'La réouverture est rapportée aux clôtures du périmètre : 15 / 100.',['85 % serait la part non rouverte dans ce décompte.','Cela inverse le rapport.','Cela ajoute événements et base comme s’ils constituaient une variation.']),
 q('Quelle limite a une prime suivant seulement le nombre de clôtures ?', ['Elle peut inciter à négliger la qualité durable du traitement.','Elle garantit automatiquement la satisfaction.','Elle prouve que toute erreur est volontaire.','Elle mesure déjà toutes les dimensions de performance.'],'Le volume et la qualité peuvent entrer en tension ; l’incitation doit être discutée.',['Le volume ne prouve pas la satisfaction.','Un risque d’incitation ne prouve pas une intention.','Délai, qualité et autres objectifs ne sont pas tous mesurés.']),
 q('Quel ensemble d’indicateurs répond le mieux au problème décrit ?', ['Volume, délai et réouvertures définis sur des périmètres cohérents.','Volume seul pour toujours.','Nom de l’équipe uniquement.','Nombre de primes sans résultats.'],'Le tableau de bord doit relier plusieurs dimensions de l’objectif.',['Cela conserve la limite déjà identifiée.','Le nom ne mesure pas un résultat.','La prime est un dispositif, pas toute la performance.']),
 q('Les 15 erreurs démontrent-elles à elles seules une faute volontaire ?', ['Non, il faut analyser les causes et le contexte.','Oui, sans aucun autre fait.','Oui, parce qu’une prime existe.','Oui, puisque le taux est positif.'],'Le constat d’erreurs et leur cause sont des questions distinctes.',['Le contexte et les faits restent nécessaires.','L’existence d’une prime n’établit pas l’intention.','Un taux positif ne décrit pas la volonté.'])
 ],[
 card('Pilotage : pourquoi relier indicateur et objectif ?','L’indicateur est un moyen de suivre une dimension de l’objectif, pas l’objectif lui-même.','100 clôtures ne prouvent pas 100 dossiers durablement résolus.','Ne pas confondre activité comptée et valeur produite.'),
 card('Effet pervers d’indicateur : quel mécanisme rechercher ?','Une optimisation de la mesure qui dégrade un autre résultat important.','Clore rapidement des dossiers qui doivent être rouverts.','Un risque de comportement n’est pas une preuve d’intention.'),
 card('Tableau de bord : quelles définitions documenter ?','Formule, périmètre, source, fréquence, responsable et action associée.','Réouvertures de la même population rapportées aux clôtures.','Une mesure sans périmètre est difficile à comparer.'),
 card('Signal de contre-performance : que faire avant de sanctionner ?','Analyser les causes, les contraintes et les leviers réellement maîtrisables.','Formation et complexité des dossiers peuvent compter.','Ne pas transformer un résultat isolé en explication unique.')
 ]),
 DSCG4:workshop('audit','Stocks : une assertion, plusieurs preuves',
 'Atelier original. Le dossier comprend un inventaire physique, des factures d’achat et des bons d’expédition proches de la clôture. Certains articles sont abîmés. L’objectif est d’examiner existence, évaluation et rattachement à la période.',[
 ['Relier chaque pièce à l’assertion','L’observation de biens physiques éclaire leur existence au moment du contrôle. Elle ne suffit pas à justifier leur valeur. Les factures apportent des données de coût, mais un coût historique ne démontre pas que des articles abîmés peuvent encore être valorisés sans examen complémentaire.','Le sens d’un test compte. Partir des lignes de l’inventaire vers les biens aide à examiner l’existence ; partir des biens observés vers l’inventaire peut aider à examiner l’exhaustivité du recensement. La date et les mouvements entre contrôle et clôture doivent être rapprochés.'],
 ['Choisir une procédure pour la question posée','Pour le rattachement, rapprochez dates de mouvement, documents et règles de reconnaissance de l’opération. Un bon proche de la clôture ne doit pas être classé par intuition sans examiner ce qui a effectivement eu lieu. Pour les articles abîmés, recherchez état, coût et données pertinentes d’évaluation.','La conclusion présente les exceptions et les limites du travail. Aucun de ces contrôles ne remplace à lui seul l’ensemble d’une démarche d’audit. Un dossier d’examen doit expliquer risque, assertion, procédure et élément attendu, puis rattacher la conclusion à ce qui a réellement été obtenu.']],
 [['Assertion ou question','Procédure illustrative','Limite'],[['Existence','Rapprocher lignes d’inventaire et biens observés','Ne justifie pas seule la valeur'],['Évaluation','Examiner coûts, état et données de valeur','Facture seule insuffisante pour un article abîmé'],['Rattachement','Rapprocher mouvements et documents proches de clôture','Date seule sans contexte insuffisante'],['Exhaustivité du recensement','Biens observés vers les lignes d’inventaire','Périmètre du test à préciser']]],[
 q('Atelier audit des stocks : l’observation physique justifie-t-elle seule la valeur ?', ['Non, existence et évaluation sont distinctes.','Oui, un bien visible conserve toujours son coût.','Oui, même si les articles sont abîmés.','Oui, la facture devient inutile.'],'La présence matérielle ne démontre pas la valeur pertinente de l’actif.',['La valeur peut demander des contrôles complémentaires.','L’état abîmé est précisément un signal à examiner.','La facture peut apporter une donnée de coût utile.']),
 q('Partir d’une ligne d’inventaire vers le bien observé vise surtout quel contrôle ?', ['L’existence de l’élément recensé.','La totalité des biens non recensés.','Le taux d’intérêt bancaire.','La valeur certaine de toute la société.'],'Le test recherche le bien correspondant à un élément enregistré.',['Le sens inverse aide davantage à chercher des omissions de recensement.','Ce test ne mesure pas le taux bancaire.','Le contrôle d’un stock n’établit pas cette valeur globale.']),
 q('Les articles abîmés appellent quel complément principal ?', ['Un examen de leur état et de l’évaluation pertinente.','Aucun contrôle puisqu’ils existent.','Une augmentation automatique de leur valeur.','La suppression de toutes les factures.'],'Le coût documenté doit être rapproché des données pertinentes de valeur.',['Existence et évaluation ne sont pas la même assertion.','L’altération ne justifie pas cette augmentation.','Les données de coût restent utiles.']),
 q('Quelle réponse expose une procédure d’audit de façon défendable ?', ['Risque, assertion, test, preuve attendue et limite.','Seulement le nom d’un document.','Une conclusion certaine avant le test.','Une liste de normes sans lien avec le dossier.'],'La chaîne explique pourquoi le contrôle répond à une question d’audit.',['Un document ne décrit pas toute la procédure.','La conclusion dépend des éléments obtenus.','Une référence doit servir le raisonnement du dossier.'])
 ],[
 card('Audit : quelle chaîne relie un risque à la conclusion ?','Risque, assertion, procédure, élément probant, résultat et limite.','Des articles abîmés appellent un examen d’évaluation.','Ne pas conclure sur une assertion non testée.'),
 card('Inventaire : pourquoi le sens du rapprochement compte-t-il ?','Du recensement vers le bien et du bien vers le recensement ne répondent pas exactement à la même question.','Existence de l’élément enregistré ou recherche d’omission du recensement.','Ne pas qualifier tous les tests de contrôle exhaustif.'),
 card('Stock abîmé : pourquoi la facture d’achat n’est-elle pas la seule preuve utile ?','Elle documente un coût sans résoudre seule la question de la valeur pertinente.','L’état des biens et d’autres données doivent être examinés.','Le coût historique n’est pas une garantie de valeur conservée.'),
 card('Clôture : que faut-il rapprocher pour le rattachement ?','Mouvements, dates, pièces et règles de reconnaissance de l’opération.','Examiner les bons d’expédition proches de la clôture.','Une date isolée ne décrit pas tous les faits de l’opération.')
 ],[['Normes d’audit, IAASB','https://www.iaasb.org/standards-pronouncements'],S.pcg]),
 DSCG5:workshop('projets','Projet SI : budget initial et coût sur trois ans',
 'Atelier original. Budget maximal initial 120 000 €. Développement 75 000 €, migration 15 000 €, formation 10 000 €. Maintenance annoncée 12 000 € par an pendant trois ans. Comparaison en euros nominaux, sans actualisation, hors autres coûts. La réserve initiale n’est pas supposée consommée.',[
 ['La réserve n’est pas une facture','Le coût initial identifié est 100 000 € ; l’écart au budget maximal est 20 000 €. Il représente une marge disponible pour les aléas du périmètre, pas une charge déjà réalisée ni un gain certain. Si un aléa consomme cette réserve, son coût doit être documenté.','Un budget de développement ne décrit pas seul le coût de possession. Migration, formation, exploitation, support et sortie du dispositif peuvent compter. Le dossier donne ici seulement la maintenance future en complément du périmètre initial ; il ne permet pas d’inventer des économies de personnel.'],
 ['Arbitrer la valeur et le risque','Sur trois ans de maintenance, le total nominal identifié est 100 000 + 3 × 12 000 = 136 000 €. Cette somme n’inclut pas par défaut la réserve non consommée. Elle n’est pas une valeur actuelle : l’exercice précise l’absence d’actualisation.','La décision doit aussi définir critères d’acceptation, responsabilités, dépendances et réversibilité. Le respect du budget ne prouve pas que les utilisateurs peuvent réaliser leurs tâches. Prévoyez tests métier, contrôles de migration et capacité de reprise, puis présentez les limites de la comparaison.']],
 [['Périmètre','Montant','Lecture'],[['Développement + migration + formation','100 000 €','Coût initial identifié'],['Marge au budget maximal','20 000 €','Réserve non consommée'],['Maintenance sur trois ans','36 000 €','Coût nominal fourni'],['Total identifié sur l’horizon','136 000 €','Sans réserve ni coûts non donnés']]],[
 q('Atelier projet SI : quel coût initial identifié additionner ?', ['100 000 €.','120 000 €.','136 000 €.','75 000 €.'],'75 000 + 15 000 + 10 000 = 100 000 €.',['Le plafond inclut une réserve non consommée.','Ce total inclut trois ans de maintenance.','Cela ne retient que le développement.']),
 q('Quel total nominal identifié vaut pour l’horizon donné ?', ['136 000 €.','156 000 €.','112 000 €.','36 000 €.'],'100 000 + 3 × 12 000 = 136 000 €.',['Cela traite toute la réserve comme consommée sans hypothèse.','Cela ne compte qu’une année de maintenance.','Cela oublie le coût initial.']),
 q('Les 20 000 € d’écart au plafond sont-ils déjà une dépense réalisée ?', ['Non, la réserve n’est pas supposée consommée.','Oui, tout plafond est une facture.','Oui, la réserve est la maintenance.','Oui, le budget est un bénéfice.'],'Un montant disponible et un coût effectivement identifié sont distincts.',['Le plafond autorisé n’est pas le coût facturé.','La maintenance est une donnée séparée.','Un budget n’est pas un bénéfice réalisé.']),
 q('Un projet respecte le budget. Quel contrôle reste indispensable ?', ['Son acceptation métier et la qualité des données migrées.','Aucun, le budget suffit à tout valider.','Seulement la couleur du logo.','La suppression des tests de reprise.'],'La réussite du SI inclut usages, données, continuité et critères définis.',['Un coût conforme ne démontre pas un fonctionnement conforme.','La couleur ne valide pas le besoin métier.','La continuité doit être éprouvée, pas supprimée.'])
 ],[
 card('Projet SI : budget maximal et coût réalisé sont-ils identiques ?','Non. Un plafond, une réserve et une dépense identifiée répondent à des objets distincts.','100 000 € identifiés pour un plafond initial de 120 000 €.','Ne pas consommer comptablement une réserve par défaut.'),
 card('Coût de possession : pourquoi élargir l’horizon ?','Le développement initial ne décrit pas tous les coûts d’exploitation et de sortie.','Trois ans de maintenance donnée ajoutent 36 000 €.','Comparer les mêmes périodes et périmètres.'),
 card('Somme nominale et valeur actuelle : quelle différence ?','La valeur actuelle utilise une actualisation cohérente ; une somme nominale additionne les montants du cadre donné.','136 000 € ici est un total sans actualisation.','Ne pas présenter cette somme comme une VAN.'),
 card('Acceptation SI : quels résultats ne remplace pas le respect du budget ?','Usages métier, qualité des données, sécurité et continuité attendue.','Tester les données migrées et les tâches essentielles.','Le budget conforme n’est pas une preuve universelle de réussite.')
 ],[S.cyber]),
 DSCG6:workshop('argumenter','A recommendation that survives an objection',
 'Original written practice. A company considers outsourcing support. A proposal estimates a 15% direct cost reduction. Service quality and data safeguards have not been independently assessed. The task is to recommend the next step, not to guarantee the outcome.',[
 ['Build a claim with a condition','A defensible position can acknowledge potential savings while requiring evidence on service and data risks. “The proposal estimates a 15% reduction” keeps the source and status of the figure clear. “Outsourcing will save 15%” turns an estimate into a certainty that the document does not establish.','Distinguish an argument from a list of facts. Explain why a fact matters to the decision and what evidence would strengthen or weaken it. An estimate of direct cost does not automatically include transition, supervision or exit costs.'],
 ['Answer an objection instead of ignoring it','A possible objection is that a lower price may reduce service quality. Do not dismiss the objection by repeating the savings figure. A proportionate response is to recommend a pilot with defined service indicators, contractual safeguards and a review of total cost.','A useful written conclusion is: “The proposal may reduce direct costs, but the company should assess service quality, data safeguards and transition costs before committing.” May marks uncertainty; but connects a limitation; before committing identifies the decision stage. The exercise prepares reasoning in writing and does not provide a live oral assessment.']],
 [['Function','Example phrase','Purpose'],[['Attribute','The proposal estimates…','Keep the source visible'],['Qualify','The project may…','Avoid unsupported certainty'],['Counterargue','However, service quality…','Address another criterion'],['Recommend','Before committing, assess…','Connect action and decision']]],[
 q('English argumentation workshop: which wording preserves the status of the cost figure?', ['The proposal estimates a 15% reduction in direct costs.','The company is guaranteed a 15% saving.','All costs will disappear.','Quality has already been independently proven.'],'The source provides an estimate of direct cost reduction, not a guaranteed total outcome.',['The proposal does not provide a guarantee.','A reduction is not disappearance.','The scenario explicitly states the missing assessment.']),
 q('Which verb best expresses a possible benefit without guaranteeing it here?', ['May.','Must, as a proven certainty.','Has always.','Cannot ever.'],'May expresses possibility and matches the status of the proposal.',['Must would overstate what is established in this context.','No history of universal results is given.','The document does not prove impossibility either.']),
 q('Which response addresses the service-quality objection?', ['Recommend a pilot with defined service indicators.','Repeat the savings number only.','Declare quality irrelevant.','Invent an independent audit result.'],'The response proposes evidence relevant to the objection.',['Repeating another criterion does not answer the concern.','Service quality is part of the support decision.','A missing assessment cannot be invented.']),
 q('Which conclusion is proportionate to the written dossier?', ['Assess quality, safeguards and transition costs before committing.','Sign immediately because the estimate is guaranteed.','Ignore all data risks.','Assume the pilot has already succeeded.'],'The recommendation connects missing evidence to the stage of decision.',['The estimate is not a guarantee.','The safeguards are explicitly unassessed.','The scenario describes no completed pilot.'])
 ],[
 card('English argumentation: claim, evidence and significance?', 'State a position, support it with evidence and explain why that evidence matters.','A direct-cost estimate is relevant but incomplete for an outsourcing decision.','A list of figures is not yet a developed argument.'),
 card('English uncertainty: when does may help?', 'When a benefit or consequence is possible but not established as certain.','The proposal may reduce direct costs.','Do not convert an estimate into a guarantee.'),
 card('English counterargument: what makes the response useful?', 'Address the concern with relevant evidence or a concrete condition.','A service-quality pilot responds to a quality objection.','Repeating the original claim does not answer every objection.'),
 card('Written recommendation: why identify the decision stage?', 'It makes clear what should be checked before committing or changing course.','Assess safeguards before signing the agreement.','Do not imply that missing tests have already succeeded.')
 ]),
 DSCG7:workshop('enquete','Six entretiens : comparer sans sur-généraliser',
 'Atelier original. Une enquête qualitative comprend six entretiens de volontaires dans une équipe. Quatre évoquent des reprises fréquentes. L’élève dispose aussi d’une procédure écrite et de dix dossiers anonymisés. Les participants ne constituent pas un échantillon probabiliste.',[
 ['Dire ce que le recueil permet','Les entretiens peuvent documenter pratiques, perceptions et mécanismes dans ce terrain. Quatre participants sur six évoquent une difficulté, mais ce rapport ne devient pas un taux statistique représentatif de toute l’entreprise. Le mode de recrutement et le périmètre doivent accompagner la présentation.','Un guide d’entretien ouvre des questions et relances comparables sans forcer toutes les réponses. Le codage rassemble des unités de sens selon des catégories explicites. Une citation illustre un résultat, mais une phrase spectaculaire ne remplace pas l’analyse du corpus.'],
 ['Trianguler et discuter les contradictions','La procédure décrit le fonctionnement prévu ; les entretiens décrivent des expériences ; les dossiers documentent certains traitements observables. Une divergence entre ces sources peut révéler une variation de pratique, une limite de mesure ou un élément manquant. Elle ne prouve pas automatiquement que quelqu’un ment.','Conservez une trace entre extrait, code, thème et interprétation. Limitez les données identifiantes selon la finalité et protégez les conditions d’accès. La discussion présente la portée locale, les biais possibles et les hypothèses que le terrain n’a pas permis de trancher.']],
 [['Source','Ce qu’elle renseigne','Limite'],[['Six entretiens volontaires','Perceptions et pratiques rapportées','Pas de représentativité statistique automatique'],['Procédure écrite','Fonctionnement prescrit','Ne prouve pas l’application effective'],['Dix dossiers anonymisés','Traces de traitements examinés','Périmètre et sélection à expliquer'],['Comparaison des sources','Convergences et contradictions','Ne supprime pas tous les biais']]],[
 q('Atelier mémoire : quatre entretiens sur six évoquent une reprise. Que peut-on affirmer ?', ['Quatre participants de ce terrain l’ont évoquée.','Deux tiers de toute l’entreprise ont forcément ce problème.','Le recrutement volontaire élimine tout biais.','La procédure est certainement fausse.'],'Le résultat décrit les participants rencontrés, pas une fréquence représentative de toute l’entreprise.',['Le mode de sélection ne justifie pas cette extrapolation.','Le volontariat peut justement influencer les profils rencontrés.','Les entretiens ne suffisent pas à invalider toute la procédure.']),
 q('Que décrit principalement la procédure écrite dans cet atelier ?', ['Le fonctionnement prescrit.','Toutes les pratiques réellement appliquées.','Les réponses futures de l’enquête.','Une causalité déjà démontrée.'],'Le document prescrit un processus ; sa mise en œuvre demande d’autres observations.',['Prescription et application sont distinctes.','Le document ne prédit pas le corpus.','Une procédure seule ne démontre pas ce lien causal.']),
 q('Quel enchaînement rend le codage plus traçable ?', ['Extrait, code, thème, interprétation.','Conclusion inventée, puis citation fabriquée.','Thème sans aucun extrait.','Nom du participant comme explication universelle.'],'La chaîne montre comment une donnée soutient une catégorie puis une interprétation.',['Cela inverse la démarche et invente des données.','Le thème doit pouvoir être relié au corpus.','L’identité ne remplace pas l’analyse des données.']),
 q('Entretiens et dossiers divergent. Quelle démarche retenir ?', ['Examiner les périmètres, les pratiques et les limites de chaque source.','Conclure immédiatement que quelqu’un ment.','Supprimer la source gênante sans analyse.','Déclarer que la triangulation élimine tous les biais.'],'La contradiction est un objet d’analyse et demande une explication documentée.',['Plusieurs explications sont possibles.','Cela déforme le terrain et la discussion.','Croiser des sources ne garantit pas une absence de biais.'])
 ],[
 card('Enquête qualitative : pourquoi préciser le recrutement ?', 'Il éclaire quels points de vue ont pu entrer dans le terrain et les biais possibles.','Six volontaires ne décrivent pas automatiquement toute l’entreprise.','Ne pas annoncer une représentativité statistique sans fondement.'),
 card('Codage : quelle trace garder de la donnée à l’analyse ?', 'Extrait, code, thème et interprétation avec une logique explicitée.','Une citation est reliée à une catégorie d’analyse.','Ne pas fabriquer une preuve après la conclusion.'),
 card('Triangulation : que comparer concrètement ?', 'Les apports, convergences, divergences et limites de plusieurs sources.','Procédure, entretiens et traces de dossiers éclairent des aspects différents.','Croiser les sources ne fait pas disparaître tous les biais.'),
 card('Mémoire : comment présenter une contradiction de terrain ?', 'La décrire et examiner ses explications possibles avant de conclure.','Pratique rapportée différente de la procédure prescrite.','La contradiction ne démontre pas automatiquement un mensonge.')
 ],[S.privacy]),
};
SUBJECT_WORKSHOPS.UE8.code='SELECT C.id, COUNT(F.id) AS factures,\n       COALESCE(SUM(F.montant_ht), 0) AS total_ht\nFROM CLIENT C\nLEFT JOIN FACTURE F ON F.client_id = C.id\nGROUP BY C.id;';
export function enrichSubjectChapter(module,c){
 const extra=SUBJECT_WORKSHOPS[module];
 if(!extra||extra.chapter!==c.id)return c;
 c.workshop=extra;
 c.quiz.push(...extra.quiz.map(n=>({...n,title:extra.title})));
 c.cards.push(...extra.cards.map(n=>({...n,tag:c.title})));
 c.sources=[...new Map([...c.sources,...extra.sources].map(source=>[source[1],source])).values()];
 return c;
}
